Sort tbody list which is populated with Javascript getList?

I have a router with a DHCP page which is not sorted by the internal IP number, instead it is fully random. I have full access to the html and javascript, and I can modify this without any issues. However I cannot figure out how to make the list sorted by IP-address by default. I have no need to be able to manually click and sort, I just want the list to always be sorted by IP-address.

I cannot figure out if it is possible to sort a getList, or if it has to be done in the randerBandlist function.

The list html:
```
                <table class="table">
                <thead>
                    <tr>
                        <th width="30"></th>
                        <th><%:设备名称%></th>
                        <th><%:IP地址%></th>
                        <th><%:MAC地址%></th>
                        <th width="150" class="center"><%:操作%></th>
                    </tr>
                </thead>
                <tbody id="bandlist">
                    <tr>
                        <td class="center" colspan="5"><%:查询中...%></td>
                    </tr>
                </tbody>
            </table>
```

This is the part that handles the list in question:
```
getList = function( callback ){
        $.getJSON('<%=luci.dispatcher.build_url("api", "xqnetwork","macbind_info")%>',{},function(rsp){
            if ( rsp.code != 0 ) {
                return;
            }
            callback( rsp );
        });
    },
    randerBandlist = function( rsp ){
        var tpl = $( '#tplbandlist' ).html(),
            container = $( '#bandlist' ),
            bandlistdata = rsp.list,
            tpldata = [],
            mac, ip, dname;
        currentList = {};
        if ( bandlistdata.length > 0 ) {
            for (var i = 0; i < bandlistdata.length; i++) {
                mac = bandlistdata[i].mac.toUpperCase();
                ip = bandlistdata[i].ip;
                dname = StringH.encode4Html( bandlistdata[i].name );
                tpldata.push({
                    dname: dname,
                    ip: ip,
                    mac: mac
                });
                currentList[ip] = 1;
            }
        }
        container.html( tpl.tmpl( {bandlist: tpldata} ) );
    },
return {
    init: function(){
        getList( randerBandlist );
        addEvent();
    }
}
```

